-- Lot 212 : payloads 331 a 360 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-207","moteur":"chatgpt","payload":"[RaccourcIA — /windowdisplay]\n\nMISSION\nConcevoir une vitrine qui attire depuis la rue. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Vitrine commerciale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"6fd4fd11c1bd0ccf66f5489eb04c3003211a61afc6d4bb87ce695e7ddf0d4dcb"},{"ref":"RCI-IMG-207","moteur":"claude","payload":"[RaccourcIA — /windowdisplay]\n\nMISSION\nConcevoir une vitrine qui attire depuis la rue. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Vitrine commerciale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"59c475a8b09751ae8e6883df94eaed9f5e03220cba603f6fcfeca99640b034e9"},{"ref":"RCI-IMG-207","moteur":"gemini","payload":"[RaccourcIA — /windowdisplay]\n\nMISSION\nConcevoir une vitrine qui attire depuis la rue. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Vitrine commerciale » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Place produit héros, plans secondaires et éclairage tout en gardant accès et visibilité. Préserve la structure réelle et n’invente pas de surface disponible. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"88b2990bdeb5b9e684ed1ebc1f1cf223c2e7c8a7a03264c2fa3003a8a87c7b3b"},{"ref":"RCI-IMG-025","moteur":"chatgpt","payload":"[RaccourcIA — /headshot]\n\nMISSION\nTransformer un portrait en photo professionnelle. Cadre tête-épaules, lumière douce et fond uni; garde visage, âge apparent et texture de peau. Aucun rôle professionnel n’est présumé.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage doit guider le portrait : CV, LinkedIn, équipe d’entreprise ou autre ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Headshot pro » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Cadre tête-épaules, lumière douce et fond uni; garde visage, âge apparent et texture de peau. Aucun rôle professionnel n’est présumé. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /headshot: Cadre tête-épaules, lumière douce et fond uni; garde visage, âge apparent et texture de peau. Aucun rôle professionnel n’est présumé. Mode /corporateportrait: Fond, lumière et cadrage suivent une charte commune; garde personnalité et traits. N’ajoute ni badge ni fonction non confirmée. Mode /cvportrait: Cadrage tête-épaules sobre et expression accessible, fond neutre. N’invente pas d’uniforme, de diplôme ou d’expérience professionnelle. Mode /linkedinportrait: Visage lisible en vignette circulaire, regard ouvert, fond discret. Garde de l’espace autour de la tête et une retouche naturelle. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"c1f0841c48782ec5b912973d3a85bccf7448d82ea3e7d3946827c58ccade76b4"},{"ref":"RCI-IMG-025","moteur":"claude","payload":"[RaccourcIA — /headshot]\n\nMISSION\nTransformer un portrait en photo professionnelle. Cadre tête-épaules, lumière douce et fond uni; garde visage, âge apparent et texture de peau. Aucun rôle professionnel n’est présumé.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage doit guider le portrait : CV, LinkedIn, équipe d’entreprise ou autre ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Headshot pro » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Cadre tête-épaules, lumière douce et fond uni; garde visage, âge apparent et texture de peau. Aucun rôle professionnel n’est présumé. Reconnais le